}


/* Kernel implementation in Exo:
EXO START
from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

@proc
def kernel_mvt(
    n: size,
    x1: DATA_TYPE[n] @ DRAM,
    x2: DATA_TYPE[n] @ DRAM,
    y_1: DATA_TYPE[n] @ DRAM,
    y_2: DATA_TYPE[n] @ DRAM,
    A: DATA_TYPE[n, n] @ DRAM,
):
    assert n > 0

    # First matrix-vector product:
    #   x1[i] += sum_j A[i, j] * y_1[j]
    for i in seq(0, n):
        for j in seq(0, n):
            x1[i] += A[i, j] * y_1[j]

    # Second matrix-vector product:
    #   x2[i] += sum_j A[j, i] * y_2[j]
    for i in seq(0, n):
        for j in seq(0, n):
            x2[i] += A[j, i] * y_2[j]


# ---------------------------------------------------------------------------
# Optimization schedule
#
# Goals:
#  - Improve computational efficiency by unrolling the inner j-loops.
#  - Expose parallelism by parallelizing the outer i-loops (rows are independent).
#  - Keep the memory access pattern of A identical to the original code.
#
# Strategy:
#  1. For each mat-vec, split the inner j-loop into (j_outer, j_inner) with a
#     small constant tile size T_J and a guarded tail. This gives a fixed-trip
#     inner loop amenable to unrolling and vectorization.
#  2. Fully unroll the inner j_inner loop.
#  3. Parallelize the outer i-loop of each mat-vec using Exo's parallelize_loop
#     primitive, which will lower to OpenMP in C.
# ---------------------------------------------------------------------------

T_J = 4  # tile factor for the inner j loops

kernel_mvt_opt = kernel_mvt

# ---- First mat-vec: x1 update ---------------------------------------------

# Tile the inner j loop under the first i-loop.
i0 = kernel_mvt_opt.find_loop("i")          # first outer i loop
j0 = i0.body().find_loop("j")               # its inner j loop
kernel_mvt_opt = divide_loop(
    kernel_mvt_opt,
    j0,
    T_J,
    ("j_outer", "j_inner"),
    tail="guard",
)

# Unroll the small fixed-size inner loop (j_inner runs from 0 to T_J-1).
j_inner0 = kernel_mvt_opt.find_loop("j_inner")
kernel_mvt_opt = unroll_loop(kernel_mvt_opt, j_inner0)

# Parallelize the outer i loop of the first mat-vec.
i0 = kernel_mvt_opt.find_loop("i")
kernel_mvt_opt = parallelize_loop(kernel_mvt_opt, i0)


# ---- Second mat-vec: x2 update --------------------------------------------

# The second i-loop is matched as "i #1" (the second occurrence of loop 'i').
i1 = kernel_mvt_opt.find_loop("i #1")
j1 = i1.body().find_loop("j")
kernel_mvt_opt = divide_loop(
    kernel_mvt_opt,
    j1,
    T_J,
    ("j_outer_2", "j_inner_2"),
    tail="guard",
)

# Unroll the inner j_inner_2 loop for the second mat-vec.
j_inner1 = kernel_mvt_opt.find_loop("j_inner_2")
kernel_mvt_opt = unroll_loop(kernel_mvt_opt, j_inner1)

# Parallelize the outer i loop of the second mat-vec.
i1 = kernel_mvt_opt.find_loop("i #1")
kernel_mvt_opt = parallelize_loop(kernel_mvt_opt, i1)


# Expose the optimized kernel under the original name expected by the driver.
kernel_mvt = kernel_mvt_opt

EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A,   DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(x1,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x2,  DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_1, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y_2, DATA_TYPE, N, n);

  /* Initialize array(s). */
  init_array (n,
	      POLYBENCH_ARRAY(x1),
	      POLYBENCH_ARRAY(x2),
	      POLYBENCH_ARRAY(y_1),
	      POLYBENCH_ARRAY(y_2),
	      POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten PolyBench views to 1D pointers. */
  kernel_mvt(/*ctxt=*/NULL, n,
             (DATA_TYPE*)POLYBENCH_ARRAY(x1),
             (DATA_TYPE*)POLYBENCH_ARRAY(x2),
             (DATA_TYPE*)POLYBENCH_ARRAY(y_1),
             (DATA_TYPE*)POLYBENCH_ARRAY(y_2),
             (DATA_TYPE*)POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n,
                                    POLYBENCH_ARRAY(x1),
                                    POLYBENCH_ARRAY(x2)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x1);
  POLYBENCH_FREE_ARRAY(x2);
  POLYBENCH_FREE_ARRAY(y_1);
  POLYBENCH_FREE_ARRAY(y_2);

  return 0;
}
