from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# Baseline MVT kernel: two matrix-vector multiplies:
#   x1 = x1 + A * y_1
#   x2 = x2 + A^T * y_2
@proc
def kernel_mvt(
    n: size,
    x1: DATA_TYPE[n] @ DRAM,
    x2: DATA_TYPE[n] @ DRAM,
    y_1: DATA_TYPE[n] @ DRAM,
    y_2: DATA_TYPE[n] @ DRAM,
    A: DATA_TYPE[n, n] @ DRAM,
):
    assert n > 0

    # First matrix-vector multiply: x1[i] accumulates a dot product of
    # row i of A with y_1. We keep a scalar accumulator in a register
    # to reduce loads/stores of x1[i].
    for i in seq(0, n):
        acc1: DATA_TYPE
        acc1 = x1[i]
        for j in seq(0, n):
            acc1 += A[i, j] * y_1[j]
        x1[i] = acc1

    # Second matrix-vector multiply with transpose: x2[i] accumulates
    # a dot product of column i of A with y_2. Again, a scalar
    # accumulator keeps x2[i] in a register during the inner loop.
    for i in seq(0, n):
        acc2: DATA_TYPE
        acc2 = x2[i]
        for j in seq(0, n):
            acc2 += A[j, i] * y_2[j]
        x2[i] = acc2


# ------------------------
# Scheduling for performance
# ------------------------

# Tile the inner j loops to improve cache locality on y_1 / y_2 and
# to give the backend a regular inner loop shape that is friendly to
# SIMD vectorization. Edge iterations are handled safely via guards.
tile_j = 32

# Tile j in the first GEMV (x1 += A * y_1).
kernel_mvt = divide_loop(kernel_mvt, "j #0", tile_j,
                         ("j_outer_1", "j_inner_1"))

# Tile j in the second GEMV (x2 += A^T * y_2).
# After the first divide, only the second GEMV still has a loop
# with iterator named exactly 'j', so the plain "j" pattern selects it.
kernel_mvt = divide_loop(kernel_mvt, "j", tile_j,
                         ("j_outer_2", "j_inner_2"))

# Parallelize the outer i loops of both GEMVs. Each iteration of the
# i-loop writes to a distinct element of x1/x2 and therefore can be
# evaluated independently in parallel.
kernel_mvt = parallelize_loop(kernel_mvt, "i #0")
kernel_mvt = parallelize_loop(kernel_mvt, "i #1")

EXO END
*/


