from __future__ import annotations

from exo import *
from exo.API_scheduling import *
from exo.libs.memories import DRAM

# Fused and optimized matrix-vector transpose kernel for MVT.
# This version traverses each row of A only once and reuses the loaded
# matrix element for both x1 and x2 updates, improving data locality.

@proc
def kernel_mvt(
    n: size,
    x1: DATA_TYPE[n] @ DRAM,
    x2: DATA_TYPE[n] @ DRAM,
    y_1: DATA_TYPE[n] @ DRAM,
    y_2: DATA_TYPE[n] @ DRAM,
    A: DATA_TYPE[n, n] @ DRAM,
):
    for i in seq(0, n):
        # Accumulator for x1[i], kept in a scalar (register) across the row.
        acc1: DATA_TYPE
        acc1 = x1[i]

        # Value from y_2 corresponding to this row.
        tmp2: DATA_TYPE
        tmp2 = y_2[i]

        for j in seq(0, n):
            # Load A[i, j] once and reuse for both updates.
            a_ij: DATA_TYPE
            a_ij = A[i, j]

            # x1[i] += A[i, j] * y_1[j]
            acc1 += a_ij * y_1[j]

            # x2[j] += A[i, j] * y_2[i]
            # This is algebraically equivalent to the original:
            #   x2[i] += A[j, i] * y_2[j]
            # after reindexing the double sum.
            x2[j] += a_ij * tmp2

        # Commit the accumulated result for this row.
        x1[i] = acc1


# ---------------------------------------------------------------------------
# Scheduling: tile the inner j loop to improve cache locality and make the
# innermost loop more amenable to vectorization by the C compiler.
# ---------------------------------------------------------------------------

kernel_mvt_opt = kernel_mvt

# Tile size for the j dimension (must be a positive integer).
TILE_J = 64

# Split the j loop into:
#   jo : tile index
#   ji : index within a tile
kernel_mvt_opt = divide_loop(kernel_mvt_opt, "j", TILE_J, ["jo", "ji"], tail="guard")

# Keep the public C entry point name as kernel_mvt.
kernel_mvt = rename(kernel_mvt_opt, "kernel_mvt")
EXO END
*/


